// Inlined from workflows/drafts/consent/open-request.js (offline-tested). See consent-engine.md.
const c = $('When Executed by Another Workflow').first().json || {};
function computeDeadline(now,start,cfg){const n=new Date(now).getTime();const s=new Date(start).getTime();const w=(cfg&&cfg.maxWindowH?cfg.maxWindowH:24)*3600*1000;const l=(cfg&&cfg.minLeadMin?cfg.minLeadMin:60)*60*1000;return new Date(Math.max(n,Math.min(n+w,s-l))).toISOString();}
const now = new Date().toISOString();
const stamp = now.replace(/[-:T.]/g,'').slice(0,14);
const id = stamp + '-' + String(c.requester||'unknown');
const deadline = computeDeadline(now, c.reqStart, {maxWindowH:24, minLeadMin:60});
return [{ json: {
  'Request ID': id, 'Status': 'PENDING', 'Kind': 'PREEMPT',
  'Requester': c.requester||'', 'Requester Name': c.requesterName||'',
  'Approver': c.approver||'', 'Approver Name': c.approverName||'',
  'Room/Booth': c.room||'', 'Req Start': c.reqStart||'', 'Req End': c.reqEnd||'',
  'Incumbent Event Id': c.incumbentEventId||'', 'Incumbent Title': c.incumbentTitle||'',
  'Incumbent New Start': '', 'Incumbent New End': '',
  'Req Priority': (c.reqPriority==null?'':c.reqPriority), 'Inc Priority': (c.incPriority==null?'':c.incPriority),
  'Deadline': deadline,
  'Requester DM': c.requesterDM||'', 'Approver DM': c.approverDM||'',
  'Log Thread TS': '', 'Resolved Via': '', 'Attested By': '', 'Decided At': '',
  'Req Payload': (c.reqPayload==null?'':(typeof c.reqPayload==='string'?c.reqPayload:JSON.stringify(c.reqPayload)))
}}];

// Inlined from workflows/drafts/consent/open-request.js (offline-tested).
const c = $('When Executed by Another Workflow').first().json || {};
const R = $('Build Request').first().json || {};
function whenPhrase(s,e){try{const o={timeZone:'Asia/Manila',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'};const a=new Date(s).toLocaleString('en-US',o);const b=e?new Date(e).toLocaleTimeString('en-US',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'}):'';return b?(a+'–'+b):a;}catch(_){return String(s||'');}}
const when = c.reqStart ? whenPhrase(c.reqStart, c.reqEnd) : 'the requested time';
const incumbentDM = `Hi ${c.approverName||'there'} — ${c.requesterName||'someone'} needs ${c.room} on ${when} for a higher-priority ${c.reqType||'session'}, which would mean moving your "${c.incumbentTitle}". Are you OK to move it? If yes, just tell me what time works for your session and I'll sort it out. Reply here with yes or no.`;
const requesterReply = `${c.room} is held by "${c.incumbentTitle}" (${c.approverName}) at ${when}. Your ${c.reqType||'session'} outranks it, so I've asked ${c.approverName} to move — I'll confirm once they reply. If you've already cleared it with them, reply "cleared with ${c.approverName}".`;
const approvalsLog = `[PREEMPT] ${R['Request ID']} — PENDING\n${c.requesterName} wants ${c.room} (${when}) for ${c.reqType} (rank ${R['Req Priority']}) over "${c.incumbentTitle}" / ${c.approverName} (rank ${R['Inc Priority']}).\nAsked ${c.approverName} by DM. Deadline ${R['Deadline']}.`;
return [{ json: { incumbentDM, requesterReply, approvalsLog, approver: c.approver||'', approverDM: c.approverDM||'' } }];

return [{ json: {
  status: 'PENDING',
  request_id: $('Build Request').first().json['Request ID'],
  message: $('Build Messages').first().json.requesterReply
}}];

